"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[7078],{9441(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>h,frontMatter:()=>l,metadata:()=>i,toc:()=>p});const i=JSON.parse('{"id":"part1-enterprise-ai-delivery/architecture-review","title":"Architecture Review: Run the Review and Capture Approval Conditions","description":"This tutorial shows how to run an enterprise architecture review for the Exec Document Q&A pilot and how to walk out with a clear approval outcome and actionable conditions. It is written for an AI Lead who must align...","source":"@site/docs/part1-enterprise-ai-delivery/09-architecture-review.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/09-architecture-review","permalink":"/tutorials/part1-enterprise-ai-delivery/09-architecture-review","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":9,"frontMatter":{"title":"Architecture Review: Run the Review and Capture Approval Conditions","slug":"/part1-enterprise-ai-delivery/09-architecture-review","description":"This tutorial shows how to run an enterprise architecture review for the Exec Document Q&A pilot and how to walk out with a clear approval outcome and actionable conditions. It is written for an AI Lead who must align...","sidebar_label":"9. Architecture review","pagination_label":"9. Architecture review","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"8. After HLD: next steps","permalink":"/tutorials/part1-enterprise-ai-delivery/08-after-hld-next-steps"},"next":{"title":"10. HLD to LLD and sprint plan","permalink":"/tutorials/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan"}}');var o=n(4848),r=n(8453),a=n(8172);const s=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/09-architecture-review.html","route":"/part1-enterprise-ai-delivery/09-architecture-review","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"Architecture Review (Step 2): Run the Review and Capture Approval Conditions","title":"Architecture Review: Run the Review and Capture Approval Conditions","description":"This tutorial shows how to run an enterprise architecture review for the Exec Document Q&A pilot and how to walk out with a clear approval outcome and actionable conditions. It is written for an AI Lead who must align...","readingMinutes":5,"bodyClass":"","normalizeMath":false,"toc":[{"id":"goal","label":"1) Goal and outcomes"},{"id":"audience","label":"2) Who attends (typical enterprise roles)"},{"id":"prep","label":"3) Preparation checklist (the difference between \u201capproval\u201d and \u201crework\u201d)"},{"id":"bring","label":"4) What to bring (minimum review pack)"},{"id":"agenda","label":"5) Recommended review agenda (60 minutes)"},{"id":"questions","label":"6) Questions reviewers will ask (be ready)"},{"id":"conditions","label":"7) Capturing approval conditions (this is the most important output)"},{"id":"artifacts","label":"8) Post-review artifacts (what you send out)"},{"id":"templates","label":"9) Templates you can copy (email + meeting close)"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      This tutorial shows how to run an <strong>enterprise architecture review</strong> for the Exec Document Q&amp;A pilot\\n      and how to walk out with a <strong>clear approval outcome</strong> and <strong>actionable conditions</strong>.\\n      It is written for an AI Lead who must align Security, Platform, Data Owners, and Engineering.\\n    </p>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#goal\\">Goal and outcomes</a></li>\\n      <li><a href=\\"#audience\\">Who attends</a></li>\\n      <li><a href=\\"#prep\\">Preparation checklist</a></li>\\n      <li><a href=\\"#bring\\">What to bring</a></li>\\n      <li><a href=\\"#agenda\\">Recommended agenda</a></li>\\n      <li><a href=\\"#questions\\">Questions reviewers will ask</a></li>\\n      <li><a href=\\"#conditions\\">Capturing approval conditions</a></li>\\n      <li><a href=\\"#artifacts\\">Post-review artifacts</a></li>\\n      <li><a href=\\"#templates\\">Templates you can copy</a></li>\\n    </ul>\\n\\n    <h2 id=\\"goal\\">1) Goal and outcomes</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        <span class=\\"pill\\">Goal</span>\\n        Get <strong>Approved to build pilot</strong> (or <strong>Approved with conditions</strong>) and leave with explicit controls to satisfy.\\n      </p>\\n\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">You want to leave with</div>\\n          <ul>\\n            <li><strong>Approval outcome</strong>: approved / approved with conditions / rejected</li>\\n            <li><strong>Action items</strong> with owners + due dates</li>\\n            <li><strong>Required controls</strong>: redaction rules, log schema, data classification constraints, etc.</li>\\n            <li><strong>Decision log</strong>: what was decided and why</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">What \u201csuccess\u201d looks like</div>\\n          <ul>\\n            <li>Reviewers agree the <strong>trust boundary</strong> is safe (LLM data minimised)</li>\\n            <li>Access control is clear: <strong>org allowlist + tenant/corpus gates</strong></li>\\n            <li>Audit and observability are adequate for production governance</li>\\n            <li>Pilot scope is bounded and safe</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"ok\\">\\n        <strong>Lead-level framing:</strong> the review is not about \u201cis LLM cool?\u201d. It\u2019s about\\n        <em>risk-managed delivery</em>: identity, data boundaries, auditability, and operability.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"audience\\">2) Who attends (typical enterprise roles)</h2>\\n    <div class=\\"card\\">\\n      <p>Adjust to your org, but a good minimum set is:</p>\\n      <ul>\\n        <li><strong>Architecture/Platform</strong> (GKE, networking, landing zone patterns)</li>\\n        <li><strong>Security/IAM</strong> (identity, group gating, service accounts, secrets)</li>\\n        <li><strong>Privacy/Risk</strong> (data classification, retention, external model boundary)</li>\\n        <li><strong>Data Owner / Business Owner</strong> (corpus approval, acceptable use)</li>\\n        <li><strong>Engineering Manager</strong> (delivery plan, support model, runbooks)</li>\\n        <li><strong>AI Lead</strong> (you) and optionally <strong>AI Head</strong> (exec sponsor / escalation)</li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <strong>Tip:</strong> If your AI Head is not present, confirm they support the risk posture and pilot scope beforehand.\\n        The review goes smoother when leadership alignment is obvious.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"prep\\">3) Preparation checklist (the difference between \u201capproval\u201d and \u201crework\u201d)</h2>\\n    <div class=\\"card\\">\\n      <p><span class=\\"pill\\">Objective</span> Remove surprises before the meeting.</p>\\n      <ul>\\n        <li>Share the pack 48\u201372 hours prior.</li>\\n        <li>Do 1:1 pre-reads with Security and Platform (15\u201330 mins each) to surface blockers early.</li>\\n        <li>Confirm data classification allowed for pilot corpus (even a \u201cpilot-only\u201d constraint is fine).</li>\\n        <li>Confirm \u201cwhat goes to the LLM\u201d is explicitly stated and minimised.</li>\\n        <li>Bring your draft go-live gates (audit + eval + leakage tests) to show operational maturity.</li>\\n      </ul>\\n\\n      <div class=\\"warn\\">\\n        <strong>Common failure mode:</strong> reviewers first learn that \u201cdocuments might be sent to an external model\u201d\\n        during the meeting. Always state boundaries upfront.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"bring\\">4) What to bring (minimum review pack)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        The meeting works best when all inputs are concise and anchored on risk controls.\\n        Here is the practical minimum:\\n      </p>\\n\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Bring</th>\\n            <th>What it is</th>\\n            <th>Why reviewers care</th>\\n            <th>Minimum content</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><strong>HLD</strong></td>\\n            <td>High-level architecture + service choices</td>\\n            <td>Trust boundaries, data flows, major services</td>\\n            <td>Diagrams, service selection (with alternatives), identity model, data flow</td>\\n          </tr>\\n          <tr>\\n            <td><strong>ADRs</strong></td>\\n            <td>Decision records (\u201cwhy we chose X\u201d)</td>\\n            <td>Prevents re-litigating decisions later</td>\\n            <td>Tenant isolation, cited-only answers, model boundary, retrieval choice, eval gates</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Threat model summary</strong></td>\\n            <td>Top risks + mitigations</td>\\n            <td>Security &amp; privacy posture</td>\\n            <td>Cross-tenant leakage, injection, exfiltration, logging/PII, access abuse</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Draft go-live gates</strong></td>\\n            <td>Release criteria</td>\\n            <td>Operational readiness &amp; governance</td>\\n            <td>Audit logging fields, evaluation thresholds, leakage tests, rollback plan</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"ok\\">\\n        <strong>Shortcut:</strong> If time is tight, prioritise (1) trust boundary, (2) identity/access enforcement, (3) audit/evals.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"agenda\\">5) Recommended review agenda (60 minutes)</h2>\\n    <div class=\\"card\\">\\n      <ol>\\n        <li><strong>5 min \u2014 Purpose and decision asks</strong> (what approvals you need today)</li>\\n        <li><strong>10 min \u2014 Architecture overview</strong> (diagrams + trust boundaries)</li>\\n        <li><strong>10 min \u2014 Identity &amp; access</strong> (Workspace OIDC, org allowlist, tenant/corpus isolation)</li>\\n        <li><strong>10 min \u2014 Data flows &amp; model boundary</strong> (what is stored, what is sent to LLM, what is logged)</li>\\n        <li><strong>10 min \u2014 Threat model top risks</strong> (and mitigations)</li>\\n        <li><strong>10 min \u2014 Go-live gates</strong> (audit, evals, leakage tests, runbooks)</li>\\n        <li><strong>5 min \u2014 Decisions + conditions</strong> (capture outcome + owners)</li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>Good review behavior:</strong> move quickly from \u201cwhat it is\u201d to \u201chow we prevent bad outcomes\u201d.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"questions\\">6) Questions reviewers will ask (be ready)</h2>\\n    <div class=\\"card\\">\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Security / IAM</div>\\n          <ul>\\n            <li>How do you validate tokens and gate access?</li>\\n            <li>Where is tenant/corpus enforced?</li>\\n            <li>How do service accounts access Cloud SQL/GCS/Secret Manager?</li>\\n            <li>What is logged? Do logs contain sensitive content?</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Privacy / Risk</div>\\n          <ul>\\n            <li>What data leaves GCP to the LLM provider?</li>\\n            <li>What data classifications are allowed in the pilot?</li>\\n            <li>What\u2019s retention policy (docs, embeddings, logs)?</li>\\n            <li>How do you prevent \u201cprompt injection\u201d from documents?</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Platform / Architecture</div>\\n          <ul>\\n            <li>Why GKE vs Cloud Run? What\u2019s the platform standard?</li>\\n            <li>How will this be operated (monitoring, alerts, runbooks)?</li>\\n            <li>How do you handle dependency failures (retrieval/LLM down)?</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Business / Data owners</div>\\n          <ul>\\n            <li>Who owns the documents? Who approves inclusion/exclusion?</li>\\n            <li>What\u2019s the success metric for the pilot?</li>\\n            <li>How do we prove answers are grounded/cited?</li>\\n          </ul>\\n        </div>\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"conditions\\">7) Capturing approval conditions (this is the most important output)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Enterprises often approve with conditions. Your job is to turn those conditions into\\n        <strong>trackable work</strong> with owners and evidence required.\\n      </p>\\n\\n      <div class=\\"ok\\">\\n        <strong>Technique:</strong> re-state each condition in the meeting in plain language and confirm agreement:\\n        \u201cSo we\u2019re approved provided we do X, Y, Z. Owner A, due date B. Evidence is C.\u201d\\n      </div>\\n\\n      <h3 id=\\"example-conditions-common-for-genai\\">Example conditions (common for GenAI)</h3>\\n      <ul>\\n        <li><strong>Redaction policy</strong> for sensitive patterns before sending to LLM</li>\\n        <li><strong>Logging schema</strong> that excludes raw document content but captures citations + metadata</li>\\n        <li><strong>Data classification constraints</strong> for pilot corpus (\u201conly internal restricted, no secret/regulated\u201d)</li>\\n        <li><strong>Leakage tests</strong> that prove tenant/corpus filters work</li>\\n        <li><strong>Evaluation gates</strong> (accuracy/citation correctness thresholds)</li>\\n        <li><strong>Runbook</strong> + on-call ownership</li>\\n      </ul>\\n\\n      <h3 id=\\"condition-tracker-template-copy-paste\\">Condition tracker template (copy/paste)</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Condition</th>\\n            <th>Owner</th>\\n            <th>Due</th>\\n            <th>Evidence required</th>\\n            <th>Status</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Define and implement redaction rules before model calls</td>\\n            <td>AI Lead</td>\\n            <td>YYYY-MM-DD</td>\\n            <td>PR + tests + example before/after</td>\\n            <td>Open</td>\\n          </tr>\\n          <tr>\\n            <td>Audit log schema approved by Security (no raw snippets)</td>\\n            <td>Security + Eng</td>\\n            <td>YYYY-MM-DD</td>\\n            <td>Signed-off schema + sample logs</td>\\n            <td>Open</td>\\n          </tr>\\n          <tr>\\n            <td>Leakage test suite (cross-tenant retrieval must return 0)</td>\\n            <td>Data/Eng</td>\\n            <td>YYYY-MM-DD</td>\\n            <td>CI test results + report</td>\\n            <td>Open</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"warn\\">\\n        <strong>Anti-pattern:</strong> leaving with \u201cSecurity wants some logging controls\u201d without an owner and measurable evidence.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"artifacts\\">8) Post-review artifacts (what you send out)</h2>\\n    <div class=\\"card\\">\\n      <ul>\\n        <li><strong>Decision summary</strong> (1 page): outcome + approved scope + key decisions</li>\\n        <li><strong>Condition tracker</strong>: conditions, owners, dates, evidence</li>\\n        <li><strong>Action items list</strong>: meeting minutes with explicit assignments</li>\\n        <li><strong>Updated HLD/ADRs</strong>: incorporate agreed changes</li>\\n        <li><strong>Go-live gate checklist</strong>: what must be true before pilot launch</li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <strong>Operational tip:</strong> send the summary within 24 hours while the meeting context is fresh.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"templates\\">9) Templates you can copy (email + meeting close)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"meeting-close-script-30-seconds\\">Meeting close script (30 seconds)</h3>\\n      <p>\\n        \u201cTo close: our outcome is <strong>[approved / approved with conditions / rejected]</strong>.\\n        Conditions are <strong>[A, B, C]</strong> with owners <strong>[X, Y, Z]</strong> and due dates <strong>[d1, d2, d3]</strong>.\\n        Evidence required is <strong>[e1, e2, e3]</strong>. I\u2019ll circulate notes and the tracker today.\u201d\\n      </p>\\n\\n      <h3 id=\\"follow-up-email-skeleton\\">Follow-up email skeleton</h3>\\n      <p>\\n        Subject: <code>Architecture Review Outcome \u2014 Exec Doc Q&amp;A Pilot</code>\\n      </p>\\n      <ul>\\n        <li><strong>Outcome:</strong> Approved / Approved with conditions / Rejected</li>\\n        <li><strong>Approved scope:</strong> Pilot cohort + allowed corpora + allowed data classifications</li>\\n        <li><strong>Conditions:</strong> (link to tracker)</li>\\n        <li><strong>Action items:</strong> owners + due dates</li>\\n        <li><strong>Next checkpoint:</strong> date for condition review / go-live readiness review</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Go-live gate</strong>\\n      The review outcome should feed a single checklist covering audit\\n      evidence, model evaluation, cross-tenant leakage tests, operational\\n      runbooks, rollback, and approval-condition closure for this executive\\n      document Q&amp;A architecture.\\n    </div>\\n  </div>"}'),l={title:"Architecture Review: Run the Review and Capture Approval Conditions",slug:"/part1-enterprise-ai-delivery/09-architecture-review",description:"This tutorial shows how to run an enterprise architecture review for the Exec Document Q&A pilot and how to walk out with a clear approval outcome and actionable conditions. It is written for an AI Lead who must align...",sidebar_label:"9. Architecture review",pagination_label:"9. Architecture review",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},p=[];function u(e){return(0,o.jsx)(a.A,{content:s})}function h(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u()}}}]);